def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return default

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def step_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_p = (sx, sy)
    opp_p = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: md(c, opp_p)) if corners else self_p
        return step_toward(self_p, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("frontier_cells")
        if targets:
            best = min(targets, key=lambda p: md(pos(p, self_p), self_p))
            bp = pos(best, self_p)
            return step_toward(self_p, bp)
        return step_away(self_p, opp_p)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = min(resources, key=lambda p: md(pos(p, self_p), self_p))
        bp = pos(best, self_p)
        if md(self_p, opp_p) <= 1 and md(self_p, bp) <= 2:
            away = step_away(self_p, opp_p)
            if away != [0, 0]:
                return away
        return step_toward(self_p, bp)

    if md(self_p, opp_p) <= 1:
        return step_away(self_p, opp_p)

    return [0, 0]

